// @hrbr/registry — committed JSON-backed plugin registry entries.
import { Schema } from 'effect'
import { REGISTRY_CATALOG_ENTRIES } from '@hrbr/registry-catalog'
import { PluginRegistryEntry } from './types'

const decodePluginRegistryEntry = Schema.decodeUnknownSync(PluginRegistryEntry)

export const PLUGIN_REGISTRY: PluginRegistryEntry[] = REGISTRY_CATALOG_ENTRIES.map((entry) =>
  decodePluginRegistryEntry(entry)
)
