// ── Composio SDK-native binding ──────────────────────────────────────
//
// Composio toolkits can be invoked through Composio's REST tool-execution
// API instead of the MCP transport. Unlike MCP `tools/list`, the REST tool
// definitions carry strict input AND output JSON Schema, so exec gets real
// result types instead of `Promise<unknown>`. Execution reuses the same
// Composio connected account established during the managed-account OAuth
// flow — no re-auth, just a different invocation transport.
export const ComposioToolBinding = Schema.Struct({
  kind: Schema.Literal('composio'),
  /** Composio tool slug, e.g. `GMAIL_SEND_EMAIL`. The execute call targets this. */
  tool_slug: Schema.NonEmptyString,
  /** Owning toolkit slug, e.g. `gmail`. Informational; mirrors the source config. */
  toolkit_slug: Schema.optional(Schema.NonEmptyString),
  /** Pinned Composio tool version. Forwarded to the execute call when set. */
  version: Schema.optional(Schema.NonEmptyString),
})
export type ComposioToolBinding = typeof ComposioToolBinding.Type

